51:  function resolve(A,B,m){const n=m.n,p=m.p,ra={x:p.x-A.x,y:p.y-A.y},rb={x:p.x-B.x,y:p.y-B.y};const va=velAt(A,p),vb=velAt(B,p),rv={x:vb.x-va.x,y:vb.y-va.y};const vn=dot(rv,n);let raxn=cross(ra,n),rbxn=cross(rb,n);let den=A.inv+B.inv+raxn*raxn*A.invI+rbxn*rbxn*B.invI;if(den<=0)return;let j=-(1+Math.min(A.type==='car'?0.08:cfg.restitution,B.type==='car'?0.08:cfg.restitution))*Math.min(vn,0)/den;if(j>0){const J={x:n.x*j,y:n.y*j};impulse(A,p,{x:-J.x,y:-J.y});impulse(B,p,J);const va2=velAt(A,p),vb2=velAt(B,p),rv2={x:vb2.x-va2.x,y:vb2.y-va2.y};let t={x:rv2.x-n.x*dot(rv2,n),y:rv2.y-n.y*dot(rv2,n)},tl=Math.hypot(t.x,t.y);if(tl>.00001){t.x/=tl;t.y/=tl;raxn=cross(ra,t);rbxn=cross(rb,t);den=A.inv+B.inv+raxn*raxn*A.invI+rbxn*rbxn*B.invI;let jt=-dot(rv2,t)/den;const mu=Math.sqrt((A.type==='car'?cfg.groundFriction:cfg.friction)*(B.type==='car'?cfg.groundFriction:cfg.friction));jt=clamp(jt,-j*mu,j*mu);const T={x:t.x*jt,y:t.y*jt};impulse(A,p,{x:-T.x,y:-T.y});impulse(B,p,T);}}const slop=.002,percent=.34,cor=Math.max(m.depth-slop,0)/(A.inv+B.inv)*percent;A.x-=n.x*cor*A.inv;A.y-=n.y*cor*A.inv;B.x+=n.x*cor*B.inv;B.y+=n.y*cor*B.inv;}
52:  function ground(b){const cs=corners(b);for(const p of cs){if(p.y<0){const r={x:p.x-b.x,y:p.y-b.y};const vp=velAt(b,p);const rn=cross(r,{x:0,y:1});const den=b.inv+rn*rn*b.invI;if(den===0)continue;const j=-(1+.03)*vp.y/den;if(j>0){impulse(b,p,{x:0,y:j});const after=velAt(b,p);let jt=-after.x/(b.inv+r.y*r.y*b.invI);jt=clamp(jt,-j*cfg.groundFriction,j*cfg.groundFriction);impulse(b,p,{x:jt,y:0});}b.y+=(-p.y)*.72;}}}
55:  function step(dt){for(const b of bodies){b.vy-=cfg.gravity*dt;b.vx*=1/(1+.025*dt);b.vy*=1/(1+.01*dt);b.av*=1/(1+.5*dt);b.x+=b.vx*dt;b.y+=b.vy*dt;b.a+=b.av*dt;}const pairs=broadPairs();for(let iter=0;iter<5;iter++){for(const [i,j] of pairs){const A=bodies[i],B=bodies[j],m=collide(A,B);if(m){if((A.type==='car'||B.type==='car')&&iter===0&&m.depth>.005){const hit=A.type==='car'?A:B; dust(m.p.x,m.p.y,Math.min(9,Math.abs(hit.vx)*.32));shake=Math.max(shake,.24);}resolve(A,B,m);}}for(const b of bodies)ground(b);}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy-=cfg.gravity*.18*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);}
56:  function reset(launch){bodies=[];particles=[];elapsed=0;accumulator=0;impactCount=0;shake=0;run=launch; const wallLeft=12.65;car=body(3,.725,cfg.carW,cfg.carH,cfg.carMass,'car'); bodies.push(car);for(let z=0;z<cfg.layers;z++)for(let r=0;r<cfg.rows;r++)for(let col=0;col<cfg.cols;col++){const offset=(r&1)?.25:0;const depthOffset=(z-(cfg.layers-1)/2)*.022;const x=wallLeft+col*cfg.brickW+cfg.brickW/2+offset+depthOffset;const y=r*cfg.brickH+cfg.brickH/2+z*.006;const b=body(x,y,cfg.brickW-.006,cfg.brickH-.006,cfg.mass,'brick',z);bodies.push(b);}camera=9.5; if(launch){car.vx=cfg.speed;$('state').textContent='Test in progress';$('dot').classList.add('live');}else{$('state').textContent='Ready for baseline test';$('dot').classList.remove('live');} }
